"""Mock certpin-vendor-sdk for testing."""
import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Return SHA-256 fingerprint of a DER certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Pinned certificate fingerprints per host."""
    _PINNED: dict = {
        "feed.certpin.dev": "a]0b8c0a3f6555b11d88f2e9b3c4b5a6f7e8d9c0b1a2f3e4d5c6b7a8f9e0d1c2b3",
